using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
namespace LWS.TruckSports.Editor {
public static class SportsFragmentAuthoring {
 public static SportsFragmentRig Install(SportsEventTruck truck,string folder){var rig=truck.gameObject.AddComponent<SportsFragmentRig>();rig.truck=truck;var root=new GameObject("Pooled actual truck mesh fragments").transform;root.SetParent(truck.transform,false);string[] names={"Chassis","Cab","door rt","doors lft","Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR","Exhaust","interior","mirror lft.001","mirror rt.001"};var contact=SportsEventAuthoring.Contact(folder,"Bounded actual wreck fragments",.35f,.12f);var parts=new List<SportsFragmentRig.Piece>();foreach(var source in truck.visuals.GetComponentsInChildren<MeshFilter>(true).Where(f=>names.Contains(f.name))){var g=new GameObject("Wreck piece · "+source.name);g.layer=2;g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=source.sharedMesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterials=source.GetComponent<Renderer>().sharedMaterials;var shape=g.AddComponent<BoxCollider>();shape.center=source.sharedMesh.bounds.center;shape.size=source.sharedMesh.bounds.size;shape.sharedMaterial=contact;shape.enabled=false;var body=g.AddComponent<Rigidbody>();body.mass=source.name=="Cab"?2:source.name=="Chassis"?3:.5f;body.centerOfMass=shape.center;body.maxLinearVelocity=45;body.maxAngularVelocity=16;body.maxDepenetrationVelocity=2;body.linearDamping=.2f;body.angularDamping=.4f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.isKinematic=true;g.transform.localScale=Vector3.zero;parts.Add(new SportsFragmentRig.Piece{source=source.transform,body=body,collider=shape,renderer=renderer});}rig.pieces=parts.ToArray();if(rig.pieces.Length!=12)throw new Exception("Twelve actual truck parts required");return rig;}
 public static SportsFragmentRig InstallRigid(Rigidbody owner,MeshFilter[] meshes,string folder){var rig=owner.gameObject.AddComponent<SportsFragmentRig>();rig.sourceBody=owner;rig.sourceRenderers=meshes.Select(m=>m.GetComponent<Renderer>()).Where(m=>m!=null).ToArray();var root=new GameObject("Pooled actual NWH truck mesh fragments").transform;root.SetParent(owner.transform,false);string[] names={"Chassis","Cab","door rt","doors lft","Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR","Exhaust","interior","mirror lft.001","mirror rt.001"};var contact=SportsEventAuthoring.Contact(folder,"Bounded actual wreck fragments",.35f,.12f);var parts=new List<SportsFragmentRig.Piece>();foreach(var source in meshes.Where(f=>names.Contains(f.name))){var g=new GameObject("Wreck piece · "+source.name);g.layer=2;g.tag="Wheel";g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=source.sharedMesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterials=source.GetComponent<Renderer>().sharedMaterials;var shape=g.AddComponent<BoxCollider>();shape.center=source.sharedMesh.bounds.center;shape.size=Vector3.Max(source.sharedMesh.bounds.size,Vector3.one*.02f);shape.sharedMaterial=contact;shape.enabled=false;var body=g.AddComponent<Rigidbody>();body.mass=120;body.centerOfMass=shape.center;body.maxLinearVelocity=45;body.maxAngularVelocity=16;body.maxDepenetrationVelocity=2;body.linearDamping=.2f;body.angularDamping=.4f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.isKinematic=true;g.transform.localScale=Vector3.zero;parts.Add(new SportsFragmentRig.Piece{source=source.transform,body=body,collider=shape,renderer=renderer});}rig.pieces=parts.ToArray();if(rig.pieces.Length!=12)throw new Exception("Twelve actual full NWH truck parts required");return rig;}

}}
